 if(known(c.down30)&&known(cl(v,'rtoSec'))&&v.rtoSec>c.down30)add('SLO-15','review','One outage can consume SLO budget',`RTO=${time(v.rtoSec)}; 30-day budget=${time(c.down30)}`,'One full-length, user-visible outage in the measurement window may exceed the availability allowance; not inherently contradictory.','Clarify measurement exclusions and design impact on customer journeys.',['REQ-REL-001','REQ-DR-001']);
 if(v.topologyOverride!=='auto'||v.drOverride!=='auto')add('ADR-16','caution','Architect override active',`topology=${v.topologyOverride}; DR=${v.drOverride}`,'Chosen options override automated candidates for exploration only. Changed diagrams and exports inherit the proposal status.','Document justification, compare alternate risks, record owner and approval.',['REQ-DR-001','REQ-PLAT-002']);
