function validate(v,c,a,ctx){let blockers=[],warnings=[];const B=(id,msg,owner='Lead architect / responsible owner')=>blockers.push({id,msg,owner});const W=(id,msg,owner='Architecture / platform owner')=>warnings.push({id,msg,owner});
 if(!v.solutionName)W('OPEN-01','Initiative name is missing');if(!v.owner)W('EVID-01','Accountable owner not identified');if(!v.evidenceRef)W('EVID-02','No measurement or approval evidence reference supplied');
 for(const [k,label] of critical){const val=numeric.has(k)?cl(v,k):v[k];if(val===null||val===''||val==='unknown')B('OPEN-'+k,`${label} is unknown; resolve before formal Pre-SDD approval.`)}
 for(const k of numIds){if(v[k]!==null&&cl(v,k)===null)B('INVALID-'+k,`Invalid numeric input: ${k}.`)}
 if(v.residency==='unknown')B('OPEN-residency','Regulatory and geographic restrictions have not been assessed.');
 if(a.needsRegion&&['single','multiAZ','multiAZActive'].includes(a.topo))B('CONFLICT-region','Selected single-region placement cannot independently survive an entire region/provider outage.');
 if(v.failureScope==='az'&&a.topo==='single')B('CONFLICT-zone','Single fault-zone topology cannot tolerate loss of that zone without separate recovery.');
 if(v.failureScope==='site'&&a.topo==='single')B('CONFLICT-site','Single-site topology alone cannot tolerate loss of the entire site.');
 if(a.dr==='active'&&a.topo!=='active')B('CONFLICT-active-dr','Multi-site Active-Active was selected for DR, but the proposed topology is not active-active across independent sites. Align the designs or revise the strategy.');
 if(v.transactionNeed==='yes'&&['analytics','timeseries'].includes(a.effectiveKind))W('DB-atomicity','Analytical/time-series store cannot be assumed to meet multi-record transactional semantics; evaluate a separate OLTP store.');
 if(a.providerScope&&a.isMultiRegion&&v.target==='cloud')B('CONFLICT-provider','Two regions in one provider cannot by themselves satisfy whole-provider outage tolerance. An independent provider/hosting strategy needs assessment.');
 if(a.continuousTarget&&['host','az','site','region','provider'].includes(v.failureScope)&&!a.activeServing)B('CONFLICT-zeroRTO-topology','RTO=0 requires a continuity candidate with independently serving application capacity across the specified fault scope. Current topology is not active-serving.');
 if(a.continuousTarget&&['backup','pilot','warm'].includes(a.dr))B('CONFLICT-zeroRTO-strategy','RTO=0 is incompatible with asserting a backup, pilot-light or warm-standby recovery path as uninterrupted service. Compare continuous-serving alternatives or revise the objective.');
 if(v.failureScope==='cyber'&&(a.continuousTarget||a.zeroLossTarget))B('CONFLICT-cyber-zero','RTO=0 or RPO=0 under cyber/data corruption cannot be established by active-active or backup claims. Validate clean-state recovery boundaries and revisit the literal zero objective with business/data owners.');
 if(a.continuousTarget)W('DR-zeroRTO-unverified','Zero-second RTO is a business aspiration, not a guaranteed failover result; define outage detection/SLI granularity and test end-to-end, including partitions.');
 if(a.continuousTarget&&v.failureScope==='unknown')W('DR-zero-scope','Showing a provisional active-serving local topology does not establish whether regional/site DR is required; failure scope remains blocking.');
 if(a.zeroLossTarget&&a.activeServing)W('DATA-commit-protocol','Active-active application capacity is not proof of RPO=0. Require a validated acknowledgement/quorum/commit model, including latency and network partition trade-offs.');
 if(['site','region','provider'].includes(v.failureScope)&&a.dr==='backup'&&known(cl(v,'rtoSec'))&&cl(v,'rtoSec')<3600)W('DR-restore','Backup & Restore has no evidenced capability to meet this short RTO; run recovery tests and evaluate alternatives.');
 if(cl(v,'rpoSec')===0&&a.isMultiRegion)B('CONFLICT-rpo0','Zero-loss claim has not been demonstrated across the specified fault scope. Cross-region asynchronous replication does not ensure RPO=0.');
 if(['region','site','provider'].includes(v.failureScope)&&(!v.recoveryLabel))W('DR-location','Independent recovery location is not named or verified; diagram uses a placeholder.');
 if(v.topologyOverride!=='auto'||v.drOverride!=='auto'){if(!v.overrideReason)B('OVERRIDE-reason','Architect override requires a written rationale.');else W('OVERRIDE-review','Override requires authority review; no automatic approval.');}
 if(v.migration==='yes'&&v.sourcePlatform==='unknown')B('OPEN-migration-source','Migration source environment unknown.');
 if(v.migration==='yes'&&(!known(cl(v,'migrationGB'))||!known(cl(v,'linkMbps'))||!known(cl(v,'cutoverHours'))))W('MIG-transfer','Migration transfer and cutover cannot be estimated without volume, effective throughput and window.');
 if(v.changeType==='brownfield'&&v.migration==='no')W('BF-inventory','As-is inventory, telemetry and dependency graph must be collected even without migration.');
 if(v.residency==='yes'&&!v.regionLabel)B('RESIDENCY-region','Geographic restriction asserted but approved primary location not identified.');
 if(v.dataKind==='mixed'&&ctx.extras.length===0)W('DB-mixed','Mixed data workloads selected; add independent data workloads to assess store choices.');
 if(v.availability!==null&&known(cl(v,'availability'))&&v.availability>=99.99)W('REL-test','High availability target requires failure-mode and operational evidence; topology alone cannot prove it.');
 for(const [k,label] of critical)if(ctx.fieldStatus[k]==='confirmed'&&(!(v[k]!==null&&v[k]!==''&&v[k]!=='unknown')||!v.evidenceRef))B('STATUS-'+k,`Confirmed status for ${label} needs a real value and evidence reference.`);
 const supplied=critical.filter(([k])=>{let val=numeric.has(k)?cl(v,k):v[k];return val!==null&&val!==''&&val!=='unknown'}).length;const coverage=Math.round(supplied/critical.length*100);
 const filled=critical.filter(([k])=>ctx.fieldStatus[k]==='confirmed'&&v[k]!==null&&v[k]!==''&&v[k]!=='unknown').length;
 const evidence=filled===0?'Unverified / modeled':filled===supplied&&v.evidenceRef&&v.owner?'Source-labelled / confirmed':'Mixed estimated + confirmed';
 const approvals=['approveReqs','approveSecurity','approveArchitecture','approveRisks'].every(k=>v[k])&&!!v.approver;
 if(approvals&&filled!==critical.length)B('EVID-confirmation','User-stated G3 requires all critical requirements confirmed with traceable evidence; estimated values cannot be silently promoted.');
 if(approvals&&(!v.owner||!v.evidenceRef))B('EVID-ownership','A named accountable owner and source reference are required to make a G3 declaration.');
 const technicalHandoff=blockers.length===0&&approvals&&filled===critical.length&&!!v.owner&&!!v.evidenceRef;
 const gate=technicalHandoff?'User-attested G3 (not independently verified)':'Provisional / review required';
 return {blockers,warnings,coverage,supplied,total:critical.length,confirmed:filled,evidence,approvals,gate,technicalHandoff};
}
